_choice_enable() {
    printf 'all\tEnable all optional checks\n'
    shellcheck --list-optional | gawk '
        BEGIN { RS = ""; FS = "\n" }
        {
            name = ""; desc = ""
            for (i = 1; i <= NF; i++) {
                if ($i ~ /^name:[ \t]*/) {
                    name = $i
                    sub(/^name:[ \t]*/, "", name)
                } else if ($i ~ /^desc:[ \t]*/) {
                    desc = $i
                    sub(/^desc:[ \t]*/, "", desc)
                }
            }
            if (name != "") {
                printf "%s\t%s\n", name, desc
            }
        }
    '
}
